def rule_automaton(cells: list[int], rule: int, steps: int) -> list[int]:

    n: int = len(cells)
    table: list[int] = []
    code: int = rule
    for bit in range(8):
        table.append(code % 2)
        code = code // 2
    cur: list[int] = []
    nxt: list[int] = []
    for i in range(n):
        cur.append(cells[i])
        nxt.append(0)
    for step in range(steps):
        for i in range(n):
            left: int = cur[(i + n - 1) % n]
            right: int = cur[(i + 1) % n]
            nxt[i] = table[left * 4 + cur[i] * 2 + right]
        for i in range(n):
            cur[i] = nxt[i]
    return cur

